insert into public.week_content (week, baby_size_label, baby_length_cm, baby_weight_g, baby_development, mother_changes, tips) values
  ( 7, 'Blueberry',  1.0,    1,   'The heart is beating and tiny limb buds are forming.', 'Tiredness and nausea are common.', 'Eat small, frequent meals. Start folic acid if not already.'),
  ( 9, 'Cherry',     2.3,    2,   'Fingers and toes are starting to form.',               'Breasts may feel tender.',        'Book your first visit and blood tests.'),
  (12, 'Lime',       5.4,   14,   'Reflexes develop; the baby can make small movements.', 'Nausea often starts to ease.',    'NT scan is due between 11 and 13 weeks.'),
  (16, 'Avocado',   11.6,  100,   'The baby can hear sounds.',                             'You may feel more energetic.',    'Keep up iron and calcium tablets as advised.'),
  (20, 'Banana',    25.6,  300,   'Halfway there! The baby is swallowing and kicking.',    'You may feel the first kicks.',   'Anomaly scan is due between 18 and 22 weeks.'),
  (24, 'Corn',      30.0,  600,   'Lungs are developing quickly.',                         'Back ache may begin.',            'Sugar test (OGTT) is due between 24 and 28 weeks.'),
  (28, 'Brinjal',   37.6, 1000,   'Eyes can open and close.',                              'Third trimester begins.',         'Count baby movements every day.'),
  (33, 'Pineapple', 43.7, 1900,   'Bones are hardening.',                                  'Shortness of breath is common.',  'Discuss your birth plan with your doctor.'),
  (36, 'Papaya',    47.4, 2600,   'The baby is getting ready to turn head-down.',          'Pelvic pressure increases.',      'Keep your hospital bag ready.'),
