-- Denser high-risk schedule (fortnightly from 20w, weekly from 36w). Draft for OB review.
select 'high_risk', row_number() over (order by w), w, greatest(w - 1, 4), least(w + 1, 42),
       'High-risk review', 'Close monitoring', array['BP','Urine']
from unnest(array[8,12,16,20,22,24,26,28,30,32,34,36,37,38,39,40]) as w;






-- ------------------------------------------------------------------ auth users (OTP sign-in via Mailpit)
create function pg_temp.seed_user(p_id uuid, p_email text, p_role text, p_name text) returns void
language sql as $$
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change, email_change_token_new,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) values (
    '00000000-0000-0000-0000-000000000000', p_id, 'authenticated', 'authenticated', p_email, '', now(),
    jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email'))
      || case when p_role is null then '{}'::jsonb else jsonb_build_object('role', p_role) end,
    jsonb_build_object('full_name', p_name), now(), now(),
    '', '', '', '', '', '', '', ''
  );
  values (gen_random_uuid(), p_id, p_id::text,
          jsonb_build_object('sub', p_id::text, 'email', p_email, 'email_verified', true),
          'email', now(), now(), now());
$$;

